options.customCss:
/* ==========================================================================
   N8N Custom Chat Styling - CORREÇÃO DEFINITIVA DA BORDA
   ========================================================================== */

/* Importa a fonte do Google Fonts */
@import url('https://fonts.googleapis.com/css2?family=Montserrat:wght@700&family=Playfair+Display:wght@700&display=swap');

/* =========================
   VARIÁVEIS GLOBAIS
   ========================= */
:root {
    /* Família da Fonte */
    --chat--font-family: 'Montserrat', sans-serif;

    /* Cores Principais */
    --chat--color--primary: #FFE600;
    --chat--color--secondary: #2A2A2A;
    --chat--color-dark: #0B0B0B;
    --chat--color-white: #ffffff;
    --chat--color-light: #151515;

    /* Fundo Geral e Rodapé */
    --chat--body--background: #0B0B0B;
    --chat--footer--background: #0B0B0B;

    /* Cabeçalho */
    --chat--header--background: #0B0B0B;
    --chat--header--color: #FFE600;
    --chat--heading--font-size: 20px;

    /* Mensagens */
    --chat--message--bot--background: #FFE600;
    --chat--message--bot--color: #000000;
    --chat--message--user--background: #2A2A2A;
    --chat--message--user--color: #ffffff;

    /* Área de Input */
    --chat--input--background: #1A1A1A;
    --chat--input--text-color: #ffffff;
    --chat--input--border: 2px solid #FFE600;
    --chat--input--border-active: 2px solid #FFD000;
    --chat--input--border-radius: 10px;

    /* Botão de Envio */
    --chat--input--send--button--background: #FFE600;
    --chat--input--send--button--color: #000000;
    --chat--input--send--button--background-hover: #FFD000;

    /* Raio da Borda Geral */
    --chat--border-radius: 10px;
}

/* =========================
   ESTILOS ESPECÍFICOS (Overrides)
   ========================= */

/* FORÇA o fundo do rodapé a ser escuro e REMOVE A BORDA SUPERIOR */
.chat-footer {
    background-color: #0B0B0B !important;
    border-top: none !important; /* <<< CORREÇÃO PRINCIPAL APLICADA AQUI */
    padding: 15px !important;
}

/* Garante que o container INTERNO do input seja transparente e sem bordas */
.chat-input-container {
    background-color: transparent !important;
    border: none !important;
    padding: 0 !important;
}

/* Ajusta a área de texto para ter o fundo e bordas corretos */
.chat-textarea {
    background-color: #1A1A1A !important;
    border: 2px solid #FFE600 !important;
    border-radius: 10px !important;
    color: #ffffff !important;
}

/* Bolha de Mensagem do Bot com borda customizada */
.chat-message.bot {
    background: var(--chat--message--bot--background);
    color: var(--chat--message--bot--color);
    border-radius: 15px 15px 15px 5px;
    font-weight: 700;
    max-width: 80%;
}

/* Bolha de Mensagem do Usuário com borda customizada */
.chat-message.user {
    background: var(--chat--message--user--background);
    color: var(--chat--message--user--color);
    border-radius: 15px 15px 5px 15px;
    margin-left: auto;
    max-width: 80%;
}

/* Estilização da Barra de Rolagem */
.messages-list::-webkit-scrollbar {
    width: 6px;
}

.messages-list::-webkit-scrollbar-thumb {
    background: #FFE600;
    border-radius: 10px;
}

